const menu=document.querySelector('.menu-toggle');const mobile=document.querySelector('.mobile-nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));mobile.classList.toggle('open',open);menu.querySelector('span').textContent=open?'×':'＋'});
mobile?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(menu)menu.querySelector('span').textContent='＋'}));
const tabs=document.querySelectorAll('.tab');tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(t=>{t.classList.remove('is-active');t.setAttribute('aria-selected','false')});document.querySelectorAll('.tab-panel').forEach(p=>{p.hidden=true;p.classList.remove('is-active')});tab.classList.add('is-active');tab.setAttribute('aria-selected','true');const panel=document.getElementById('panel-'+tab.dataset.tab);panel.hidden=false;panel.classList.add('is-active')}));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
const progress=document.querySelector('.progress');addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(scrollY/Math.max(max,1)*100)+'%'});
document.querySelectorAll('.desktop-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.desktop-nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}));
